415	      source: author,
416	      text: `${quote}${m.feedback}`,
417	    });
418	  }
419	
420	  if (entries.length === 0) return "";
421	
422	  const items = entries
423	    .map(
424	      (e, i) =>
425	        `<li id="endnote-${i + 1}"><sup>${toSuperscript(i + 1)}</sup> ` +
426	        `<span class="endnote-source">${escapeHtml(e.source)}</span>: ` +
