 28	  folioId: string,
 29	  legacyPath: string,
 30	  filename: string,
 31	): Promise<void> {
 32	  const targetPath = scopedPath(folioId, filename);
 33	  const existing = await readFileAsJson<T[]>(targetPath);
 34	  if (Array.isArray(existing) && existing.length > 0) return;
 35	  const legacy = await readFileAsJson<T[]>(legacyPath);
 36	  if (!Array.isArray(legacy) || legacy.length === 0) return;
 37	  await writeFileAsJson(
 38	    targetPath,
 39	    legacy.map((entry) => ({ ...entry, folioId })),
 40	  );
 41	  await writeFileAsJson(legacyPath, []);
 42	}
