684	export function mergeBibliographyEntries(
685	  local: BibEntry[],
686	  remote: BibEntry[],
687	): BibEntry[] {
688	  const byId = new Map<string, BibEntry>();
689	  for (const entry of local) byId.set(entry.id, entry);
690	  for (const entry of remote) {
691	    const existing = byId.get(entry.id);
692	    if (!existing || bibEntryTimestamp(entry) >= bibEntryTimestamp(existing)) {
693	      byId.set(entry.id, entry);
694	    }
695	  }
696	  return Array.from(byId.values());
697	}
698	
699	function bibEntryTimestamp(entry: BibEntry): number {
700	  return entry.createdAt ?? entry.accessedAt ?? 0;
701	}
